def svc_en(slug, h1, title, desc, answer, sname, sdesc, what_h2, what_html, what_src,
           methods, faqs, related, procedure=None, photos=None, hero=None, crumb_self=None):
    blocks = [
      {"t":"prose","eyebrow":"Understanding the problem","h2":what_h2,"html":what_html,"sources":what_src},
      {"t":"steps","bg":"alt","eyebrow":"What a first visit involves","h2":"How we work through it",
       "lede":"We do not begin treatment on first meeting you. The assessment comes first.",
       "items":STEPS_EN},
      {"t":"checklist","eyebrow":"What may be used","h2":"Combined according to the assessment",
       "lede":"Not every patient needs every item. What is used follows from what the examination shows.",
       "items":methods,"sources":["aca","nccih_back"]},
      {"t":"routes","bg":"alt","eyebrow":"Fees and insurance","h2":"Who usually pays for this",
       "lede":"How treatment is funded changes what paperwork you need. Pick the closest to your situation:",
       "items":PAY_ROUTES_EN},
      {"t":"facts","eyebrow":"Why here","h2":"A few objective points","items":WHY_EN},
      BYLINE_EN,
    ]
    if photos:
        blocks.insert(2, {"t":"photos","eyebrow":"At the clinic","h2":"Treatment rooms and equipment","items":photos})
    p = {
      "slug":"services/"+slug, "crumbs":[("Services","/services/")],
      "crumb_self":crumb_self or h1.split("|")[0].strip(),
      "title":title, "desc":desc, "h1":h1, "answer":answer, "cta_bg":"alt",
      "service":{"type":"MedicalProcedure" if procedure else "Service","name":sname,"desc":sdesc},
      "blocks":blocks, "faqs":faqs, "related":related, "faq_bg":"",
    }
    if hero: p["hero"] = hero
    if procedure: p["service"]["procedureType"] = procedure
    return p


